def checkSubarraySum(nums, k):
    rem_map = {0: -1}
    running_sum = 0
    for i, x in enumerate(nums):
        running_sum += x
        rem = running_sum % k
        if rem in rem_map:
            if i - rem_map[rem] >= 2:
                return True
        else:
            rem_map[rem] = i
    return False

