#include <vector>
#include <unordered_map>
using namespace std;
class Solution {
public:
    bool checkSubarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> remMap;
        remMap[0] = -1;
        int sum = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            sum += nums[i];
            int rem = sum % k;
            if (remMap.count(rem)) {
                if (i - remMap[rem] >= 2) return true;
            } else {
                remMap[rem] = i;
            }
        }
        return false;
    }
};
